<script>
 import ChildAgents from './ChildAgents.svelte';
 import ProviderSettings from './ProviderSettings.svelte';
 import GmInstructions from './GmInstructions.svelte';
 let {state:world,api,refresh,guarded,busy=false}=$props();
 let loadError=$state(false),exportReport=$state(''),contextReceipts=$state([]);
 async function exportBundle(){const bundle=await api({intent:'export'}),blob=new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='homer-markdown-bundle.json';link.click();URL.revokeObjectURL(url);exportReport=`Exported ${bundle.documents.length} authoritative Markdown documents.`;}
 async function checkExport(){const bundle=await api({intent:'export'}),result=await api({intent:'migrationDryRun',documents:bundle.documents});exportReport=JSON.stringify(result);}
 let campaignHash=$state(''),campaignName=$state('');
 let section=$state('Campaign'),campaign=$state(null),sheet=$state(null),playerRow=$state(null),profileText=$state(''),context=$state(null),name=$state(''),summaryBody=$state(''),summaryLevel=$state('chapter'),sources=$state([]),factionRow=$state(null),goals=$state(''),projectName=$state(''),progress=$state(0),intention=$state(''),mediaUrl=$state(''),mediaKind=$state('portrait'),planTitle=$state(''),planSteps=$state('');
 const clone=value=>structuredClone($state.snapshot(value));
 const operation=prefix=>prefix+'_'+crypto.randomUUID().replaceAll('-','');
 const people=$derived(world.records.filter(r=>r.type==='character')),events=$derived(world.records.filter(r=>r.type==='event'));
 const command=(intent,payload)=>api({intent:'controls',command:{intent,payload}});
 async function load(){try{const controls=await command('read');campaign=clone(controls.campaign.record.data);campaignName=controls.campaign.record.name;campaignHash=controls.campaign.hash;profileText=JSON.stringify(campaign.settings.profiles,null,2);const player=people.find(r=>r.id===campaign.playerId);playerRow=player?await api({intent:'read',id:player.id}):null;sheet=clone(playerRow?.record.data.playerSheet||{level:1,hp:{current:10,max:10},abilities:{strength:10,dexterity:10,constitution:10,intelligence:10,wisdom:10,charisma:10},currency:0,inventory:[],capabilities:[]});loadError=false;}catch(error){if(error.code!=='STALE_VIEW')loadError=true;throw error;}}
 async function saveCampaign(){await command('save',{kind:'campaign',id:'campaign',name:campaignName,operationId:operation('controls'),expectedHash:campaignHash,value:campaign});await refresh();await load();}
 async function savePlayer(){await command('save',{kind:'player',id:playerRow.record.id,operationId:operation('player'),expectedHash:playerRow.hash,value:sheet});await refresh();await load();}
 async function saveSettings(){campaign.settings.profiles=JSON.parse(profileText);await saveCampaign();}
 async function declarePlan(){campaign.plans.push({id:operation('plan'),title:planTitle,steps:planSteps.split('\n').map(s=>s.trim()).filter(Boolean),status:'declared',actorId:campaign.playerId,evidenceIds:[]});await saveCampaign();planTitle='';planSteps='';}
 async function summarize(){const sourceRows=world.records.filter(r=>sources.includes(r.id)),number=world.records.filter(r=>r.type==='chapter'&&r.data.level===summaryLevel).length+1;await command('summary',{operationId:operation('summary'),id:operation('chapter'),name:name||`${summaryLevel} ${number}`,level:summaryLevel,number,body:summaryBody,sources:Object.fromEntries(sourceRows.map(r=>[r.id,r.hash]))});await refresh();name='';summaryBody='';}
 async function createFaction(){const record={schemaVersion:1,id:operation('faction'),type:'faction',name:name||'New faction',revision:1,visibility:'secret',data:{houseId:null,goals:[],intentions:[],projects:[]}};await api({intent:'create',create:{operationId:operation('create'),record}});await refresh();await selectFaction(record.id);name='';}
 async function selectFaction(id){factionRow=await api({intent:'read',id});goals=factionRow.record.data.goals.join('\n');}
 async function saveFaction(){const data=clone(factionRow.record.data);data.goals=goals.split('\n').map(s=>s.trim()).filter(Boolean);if(intention.trim())data.intentions.push({id:operation('intent'),actorId:campaign.activePovId||campaign.playerId,category:'politics',intent:intention,status:'proposed',sourceEventIds:sources,knownBy:[]});if(projectName.trim())data.projects.push({id:operation('project'),title:projectName,participants:[campaign.playerId],resourceId:null,progress:Number(progress),status:'active',sourceEventIds:sources,knownBy:[]});await command('save',{kind:'faction',id:factionRow.record.id,operationId:operation('faction'),expectedHash:factionRow.hash,value:data});await refresh();await selectFaction(factionRow.record.id);intention='';projectName='';}
 async function saveMedia(){const record={schemaVersion:1,id:operation('asset'),type:'asset',name:name||'Local '+mediaKind,revision:1,visibility:'secret',data:{kind:mediaKind,description:'Author supplied local media',sourceEventIds:sources,subjectIds:[campaign.playerId],knownBy:[],dataUrl:mediaUrl,providerStatus:'local-only'}};await command('media',{operationId:operation('media'),record,expectedSources:Object.fromEntries(world.records.filter(r=>sources.includes(r.id)).map(r=>[r.id,r.hash]))});await refresh();name='';mediaUrl='';}
 async function upload(event){const file=event.target.files?.[0];if(!file)return;if(file.size>32000)throw Error('Choose a local file smaller than 32 KiB.');mediaUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}
 $effect(()=>{if(!campaign&&!busy&&!loadError)void guarded(load);});
</script>
<section aria-label="Campaign controls" class="controls">
 <h1>Campaign controls</h1><fieldset disabled={busy}><nav aria-label="Campaign controls">{#each ['Campaign','Player','Settings','GM agent','Assistant agent','Agents','Factions','Chapters','Media','Context'] as label}<button class:active={section===label} onclick={()=>{section=label;if(label==='Context')guarded(async()=>{context=await api({intent:'context'});contextReceipts=await api({intent:'contextReceipts'});});}}>{label}</button>{/each}</nav>
 {#if campaign}
 {#if section==='Campaign'}
 <h2>Player, viewpoint and scene</h2><label>Campaign name<input id="campaign-name" bind:value={campaignName}/></label><label>Campaign description<textarea id="campaign-description" bind:value={campaign.description}></textarea></label><label>Player<select id="control-player" bind:value={campaign.playerId}>{#each people as person}<option value={person.id}>{person.name}</option>{/each}</select></label><label>Viewpoint<select id="control-pov" bind:value={campaign.activePovId}>{#each people as person}<option value={person.id}>{person.name}</option>{/each}</select></label><label>Scene<select id="control-scene" bind:value={campaign.sceneLocationId}>{#each world.records.filter(r=>r.type==='location') as place}<option value={place.id}>{place.name}</option>{/each}</select></label><button onclick={()=>guarded(saveCampaign)}>Save campaign controls</button>
 <h2>Library export</h2><button onclick={()=>guarded(exportBundle)}>Download Markdown bundle</button><button onclick={()=>guarded(checkExport)}>Check export roundtrip</button><p>{exportReport}</p><h2>Declared plans</h2><label>Plan title<input id="plan-title" bind:value={planTitle}/></label><label>Steps, one per line<textarea id="plan-steps" bind:value={planSteps}></textarea></label><button disabled={!planTitle.trim()||!planSteps.trim()||!campaign.playerId} onclick={()=>guarded(declarePlan)}>Declare plan</button>{#each campaign.plans as plan}<article><strong>{plan.title}</strong><select aria-label={'Plan status '+plan.title} bind:value={plan.status}><option>declared</option><option>pursuing</option><option>completed</option><option>abandoned</option></select><p>{plan.steps.join(' → ')}</p></article>{/each}<button onclick={()=>guarded(saveCampaign)}>Save plan progress</button>
 {:else if section==='Player'}
 <h2>{playerRow?.record.name||'Choose a player'} — character sheet</h2>{#if playerRow}<label>Level<input id="player-level" type="number" min="1" max="100" bind:value={sheet.level}/></label><label>HP<input id="player-hp" type="number" min="0" bind:value={sheet.hp.current}/></label><label>Maximum HP<input type="number" min="1" bind:value={sheet.hp.max}/></label><label>Currency<input type="number" min="0" bind:value={sheet.currency}/></label>{#each Object.keys(sheet.abilities) as ability}<label>{ability}<input type="number" min="1" max="30" bind:value={sheet.abilities[ability]}/></label>{/each}<h3>Inventory</h3>{#each sheet.inventory as item}<label>Item<input bind:value={item.name}/></label><label>Quantity<input type="number" min="0" bind:value={item.quantity}/></label>{/each}<button onclick={()=>sheet.inventory.push({id:operation('item'),name:'New item',quantity:1,resourceId:null})}>Add inventory item</button><label>Capabilities<textarea id="player-capabilities" value={sheet.capabilities.join('\n')} oninput={event=>sheet.capabilities=event.target.value.split('\n').filter(Boolean)}></textarea></label><button onclick={()=>guarded(savePlayer)}>Save player sheet</button>{/if}
 {:else if section==='Settings'}
 <h2>Generation and budgets</h2><ProviderSettings operatorSetup={world.operatorSetup} settings={campaign.settings} {api} {guarded} {busy} onchange={next=>{campaign.settings=next;profileText=JSON.stringify(next.profiles,null,2);}} onsave={saveSettings}/><p>{world.controls.providerDispatchAllowed?'Provider dispatch has an explicit host grant. Profiles and saved budgets select each role.':'Provider dispatch has no host grant. Profiles save configuration; no keys are stored here.'}</p><label>Generation mode<select id="provider-mode" bind:value={campaign.settings.mode}>{#if !world.operatorSetup?.available}<option value="synthetic">Synthetic qualification</option>{/if}<option value="disabled">Disabled</option><option value="provider">Configured provider — requires host grant</option></select></label>{#each ['gm','npc','assistant'] as role}<label>{role} profile<select bind:value={campaign.settings.selection[role]}>{#each campaign.settings.profiles as profile}<option value={profile.id}>{profile.name}</option>{/each}</select></label>{/each}<details><summary>Provider profiles</summary><label>Profiles<textarea id="provider-profiles" rows="12" bind:value={profileText}></textarea></label></details>{#each Object.keys(campaign.settings.limits) as limit}<label>{limit}<input type="number" min="0" step={limit==='maxCostUsd'?'0.001':'1'} bind:value={campaign.settings.limits[limit]}/></label>{/each}<label>GM writing style<textarea id="gm-style" bind:value={campaign.preferences.gmStyle}></textarea></label><h3>GM tools</h3>{#each Object.keys(campaign.toolPolicy) as tool}<label><input type="checkbox" bind:checked={campaign.toolPolicy[tool]}/>{tool}</label>{/each}<h3>Reading and context</h3><label><input id="focus-mode" type="checkbox" bind:checked={campaign.preferences.focusMode}/>Focus mode</label><label><input type="checkbox" bind:checked={campaign.preferences.thirdPerson}/>Third person</label>{#each ['fontSize','chapterThreshold','contextTokens','recentTurns'] as setting}<label>{setting}<input type="number" bind:value={campaign.preferences[setting]}/></label>{/each}<button onclick={()=>guarded(saveSettings)}>Save settings</button><p>{world.accounting.requests} reserved requests · {world.accounting.tokens} accounted tokens · ${world.accounting.costUsd} · {world.accounting.paidCalls} paid calls · {world.accounting.unresolved} unresolved reservations</p><details><summary>Reported provider usage</summary>{#each world.accounting.receipts.filter(r=>r.reportedUsage) as receipt}<p>{receipt.model}: prompt {receipt.reportedUsage.inputTokens??'Unknown'} · cached {receipt.reportedUsage.cachedInputTokens??'Unknown'} · uncached {receipt.reportedUsage.uncachedInputTokens??'Unknown'} · cache writes {receipt.reportedUsage.cacheWriteTokens??'Unknown'} · output {receipt.reportedUsage.outputTokens??'Unknown'} · reported cost {receipt.reportedUsage.providerCostUsd===null?'Unknown':'$'+receipt.reportedUsage.providerCostUsd}</p>{/each}<p>Accounted budget totals can include reservations or estimates. They are not proof of realized cache savings.</p></details>{#each world.accounting.receipts.filter(r=>r.simulation&&r.status==='unknown') as receipt}<button onclick={()=>guarded(async()=>{await command('reconcileSynthetic',{scopeId:receipt.scopeId});await refresh();})}>Close failed synthetic reservation {receipt.scopeId.slice(-8)}</button>{/each}
 {:else if section==='GM agent'}<GmInstructions {api} {guarded} {busy} runs={world.runs}/>
 {:else if section==='Assistant agent'}<GmInstructions {api} {guarded} {busy} role="assistant" runs={world.authorRuns||[]}/>
 {:else if section==='Agents'}
 <ChildAgents {api} {guarded} {busy} {people} profiles={campaign.settings.profiles}/>
 {:else if section==='Factions'}
 <h2>Faction intentions and projects</h2><p>Intentions and progress are explicit campaign records. NPC questions can propose intentions; consequences remain unresolved.</p><label>Name<input id="faction-name" bind:value={name}/></label><button onclick={()=>guarded(createFaction)}>Create faction</button>{#each world.records.filter(r=>r.type==='faction') as faction}<button onclick={()=>guarded(()=>selectFaction(faction.id))}>{faction.name}</button>{/each}{#if factionRow}<h3>{factionRow.record.name}</h3><label>House<select bind:value={factionRow.record.data.houseId}><option value={null}>Independent</option>{#each world.records.filter(r=>r.type==='house') as house}<option value={house.id}>{house.name}</option>{/each}</select></label><label>Goals<textarea id="faction-goals" bind:value={goals}></textarea></label><label>Proposed intention<input id="faction-intention" bind:value={intention}/></label><label>Project<input id="faction-project" bind:value={projectName}/></label><label>Progress<input type="number" min="0" max="1" step="0.05" bind:value={progress}/></label><button onclick={()=>guarded(saveFaction)}>Save faction</button>{#each factionRow.record.data.intentions as intent}<p>{intent.status}: {intent.intent}</p>{/each}{#each factionRow.record.data.projects as project}<p>{project.title}: {Math.round(project.progress*100)}% · {project.status}</p>{/each}{/if}
 {:else if section==='Chapters'}
 <h2>Chapters, arcs and sagas</h2><p>Accept an author summary against the exact source versions. Summaries do not establish new world events.</p><label>Summary level<select id="summary-level" bind:value={summaryLevel}><option>chapter</option><option>arc</option><option>saga</option></select></label><label>Name<input id="summary-name" bind:value={name}/></label><label>Summary<textarea id="summary-body" rows="6" bind:value={summaryBody}></textarea></label><button disabled={!sources.length||!summaryBody.trim()} onclick={()=>guarded(summarize)}>Accept source summary</button>{#each world.records.filter(r=>r.type==='chapter') as chapter}<article><h3>{chapter.name} · {chapter.data.level} {chapter.data.number}</h3><p>{chapter.data.body}</p><small>{chapter.data.sourceEventIds.join(', ')}</small></article>{/each}
 {:else if section==='Media'}
 <h2>Portraits, scenes, maps and audio</h2><p>Add local campaign media. Provider generation is disabled.</p><label>Kind<select id="media-kind" bind:value={mediaKind}><option>portrait</option><option>scene</option><option>map</option><option>audio</option></select></label><label>Name<input id="media-name" bind:value={name}/></label><label>Local file<input type="file" accept="image/png,image/jpeg,image/webp,audio/wav,audio/mpeg" onchange={event=>guarded(()=>upload(event))}/></label><label>Local data URL<textarea id="media-data" bind:value={mediaUrl}></textarea></label><button disabled={!mediaUrl} onclick={()=>guarded(saveMedia)}>Save local media</button>{#each world.records.filter(r=>r.type==='asset') as asset}<article><h3>{asset.name}</h3>{#if asset.data.kind==='audio'}<audio controls src={asset.data.dataUrl}></audio>{:else}<img alt={asset.data.description||asset.name} src={asset.data.dataUrl}/>{/if}</article>{/each}
 {:else if section==='Context'}<h2>Context preview</h2>{#if context}<p>Player: {context.campaign?.playerId} · POV: {context.campaign?.activePovId} · Scene: {context.campaign?.sceneLocationId}</p>{#each ['pinned','partial','searchable'] as mode}<h3>{mode}</h3>{#each context[mode] as record}<p>{record.name} · {record.path}</p>{/each}{/each}{/if}
 {/if}
 {#if section==='Context'}<h3>Continuity receipts</h3><p>Compacted history cites retained accepted turns. Exact choices and rolls remain in context; receipts do not change canon.</p>{#each contextReceipts as receipt}<details><summary>{receipt.id} · {receipt.sources.length} sources</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{JSON.stringify(receipt.result,null,2)}</pre></details>{/each}{/if}
 {#if ['Chapters','Media','Factions'].includes(section)}<details open><summary>Accepted source accounts</summary>{#each events as event}<label><input type="checkbox" bind:group={sources} value={event.id}/>{event.name}</label>{/each}</details>{/if}
 {/if}
</fieldset></section>
<style>fieldset{border:0;padding:0;margin:0;min-width:0}.controls{padding:10px}nav{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}button,select,input,textarea{background:#182219;color:#e7d9bb;border:1px solid #3d4937;border-radius:5px;padding:8px}button{cursor:pointer;margin:4px}.active{border-color:#b79c65}label{display:block;margin:12px 0}label>input:not([type=checkbox]),label>select,label>textarea{display:block;width:100%;box-sizing:border-box;margin-top:5px}input[type=checkbox]{margin-right:8px}h2{font:24px Georgia}p{line-height:1.6}article{border-top:1px solid #354035;padding:12px 0}img{max-width:100%;max-height:320px}@media(max-width:1099px){button,summary{min-height:44px}nav{gap:4px;flex-wrap:nowrap;overflow:auto}nav button{white-space:nowrap;margin:2px;font-size:12px}input:not([type=checkbox]),select,textarea{font-size:16px}h2{font-size:21px}.controls{padding:0}}
</style>